// My Doctor: current family doctor + (Head only) directory search and request.
import { type FormEvent, useCallback, useEffect, useState } from 'react'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { useAppSelector } from '../../store/hooks'
import { apiClient, threePortalApi, type DoctorSummaryDto, type FamilyDto } from '../../services/apiClient'
import { extractErrorMessage } from './threePortalUtils'

export function MyDoctorPage() {
  const user = useAppSelector((state) => state.auth.user)
  const isHead = user?.role === 'FAMILY_HEAD'

  const [familyId, setFamilyId] = useState<string | null>(null)
  const [current, setCurrent] = useState<DoctorSummaryDto | null>(null)
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')

  const [search, setSearch] = useState('')
  const [district, setDistrict] = useState('')
  const [directory, setDirectory] = useState<DoctorSummaryDto[]>([])
  const [searching, setSearching] = useState(false)

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const { data: family } = await apiClient.get<FamilyDto>('/families/me')
      setFamilyId(family.id)
      try {
        const { data } = await threePortalApi.getFamilyDoctor(family.id)
        setCurrent(data ?? null)
      } catch {
        setCurrent(null)
      }
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  async function runSearch(event: FormEvent) {
    event.preventDefault()
    setSearching(true)
    try {
      const { data } = await threePortalApi.getDoctorDirectory({ search: search || undefined, district: district || undefined })
      setDirectory(data)
    } catch {
      setDirectory([])
    } finally {
      setSearching(false)
    }
  }

  async function requestDoctor(doctor: DoctorSummaryDto) {
    if (!familyId) return
    try {
      await threePortalApi.requestFamilyDoctor(familyId, { doctorId: doctor.id })
      setMessage(`Request sent to ${doctor.displayName}.`)
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Request could not be sent.'))
    }
  }

  if (status === 'loading') return <LoadingState label="Loading your family doctor" />
  if (status === 'error') return <ErrorState message="Could not load your family doctor." onRetry={() => void load()} />

  return (
    <div className="page-stack">
      <header className="page-header">
        <div>
          <p className="eyebrow">Care team</p>
          <h1>My Doctor</h1>
        </div>
      </header>

      {message && <p role="status" className="status-banner">{message}</p>}

      <section className="panel">
        <h2>Current family doctor</h2>
        {current ? (
          <p>
            <strong>{current.displayName}</strong>
            {current.specialty ? ` · ${current.specialty}` : ''}
            {current.clinic ? ` · ${current.clinic}` : ''}
            {current.district ? ` · ${current.district}` : ''}
          </p>
        ) : (
          <EmptyState title="No family doctor yet" message={isHead ? 'Search below and send a request.' : 'The family head has not assigned a doctor yet.'} />
        )}
      </section>

      {isHead && (
        <section className="panel">
          <h2>Find a doctor</h2>
          <form className="form-grid" onSubmit={(event) => void runSearch(event)}>
            <label>
              Search
              <input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Name or specialty" />
            </label>
            <label>
              District
              <input value={district} onChange={(event) => setDistrict(event.target.value)} placeholder="e.g. Colombo" />
            </label>
            <button className="button button--primary" type="submit" disabled={searching}>
              {searching ? 'Searching…' : 'Search'}
            </button>
          </form>

          {directory.length === 0 ? (
            <EmptyState title="No results yet" message="Search the verified doctor directory above." />
          ) : (
            <div className="table-scroll">
              <table>
                <thead>
                  <tr>
                    <th>Doctor</th>
                    <th>Specialty</th>
                    <th>Clinic</th>
                    <th>Location</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {directory.map((doctor) => (
                    <tr key={doctor.id}>
                      <td>{doctor.displayName}</td>
                      <td>{doctor.specialty || '—'}</td>
                      <td>{doctor.clinic || '—'}</td>
                      <td>{[doctor.city, doctor.district].filter(Boolean).join(', ') || '—'}</td>
                      <td>
                        <button className="button button--secondary" type="button" onClick={() => void requestDoctor(doctor)}>
                          Request
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      )}
    </div>
  )
}
